class PlainText:
    def __init__(self, text):
        self._text = text

    def render(self):
        return self._text

    def describe(self):
        return "PlainText"


class TextDecorator:
    def __init__(self, inner):
        self.inner = inner

    def render(self):
        return self.inner.render()

    def describe(self):
        return f"{type(self).__name__}({self.inner.describe()})"

    def unwrap(self):
        return self.inner


class Upper(TextDecorator):
    def render(self):
        return self.inner.render().upper()


class Bold(TextDecorator):
    def render(self):
        return "**" + self.inner.render() + "**"


class Prefix(TextDecorator):
    def __init__(self, inner, prefix):
        super().__init__(inner)
        self.prefix = prefix

    def render(self):
        return self.prefix + self.inner.render()


class Truncate(TextDecorator):
    def __init__(self, inner, limit):
        if limit < 3:
            raise ValueError("Limit too small")
        super().__init__(inner)
        self.limit = limit

    def render(self):
        text = self.inner.render()
        if len(text) <= self.limit:
            return text
        return text[: self.limit - 3] + "..."
